      "location": "",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n▶10월~12월)2026년 전국 휴게소 만족도 조사 참여자 모집/ 만 20세 이상 ~ 만 69세 이하 휴게소 이용(예정) 국민\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.10.08. 21:20\n조회 55\n▶10월~12월)2026년 전국 휴게소 만족도 조사 참여자 모집/ 만 20세 이상 ~ 만 69세 이하 휴게소 이용(예정) 국민\n=====================================\n[대상]\n-만 20세 이상 ~ 만 69세 이하 휴게소 이용(예정) 국민\n[개요]\n- 조사 기간 : 2026년 10월 ~ 2026년 12월\n- 참여 방법\n1)소개자란[김현숙]을 반드시 입력해야 신청완료 됩니다.\n(간혹 소개자란에 본인 이름, 지인 이름, 없음, 네이버 카페... 이런식으로 적으면 접수 안 됩니다.)\n[아래 URL에 (클릭!!)하여 설문 진행해주세요.(스마트폰도 가능)\nhttps://ex-p.kmaresearch.co.kr\n2) 홈페이지 회원 가입\n3) [내정보]에서 사례비 수령 방식 선택 및 동의(가입경로 : 전문 소개자 선택 후 김현숙 기입)\n4) 교육자료 및 FAQ 확인\n5) 휴게소 방문 후 만족도 조사 참여 하면 완료!\n------------------------------------------------\n[혜택]\n1. 기본 활동 혜택(1일 최대 7곳까지 가능)\n- 첫번째 휴게소 : 최대 8,000원\n- 두번째 휴게소 : 최대 11.000원\n- 세번째부터 휴게소 : 최대 13,000원\n2. 주간 활동 혜택\n- 매주 10명에게 네이버페이 포인트 5만원 제공(한 주간 10회 이상 평가 참여자 중 추첨을 통해 지급)\n3. 월간 활동 혜택\n- 활동 중 매월 추첨을 통해 47명 대상 경품 지급\n1) 네이버 페이 포인트 5만원 * 2명\n2) 음료 쿠폰 1만원 * 15명\n3) 편의점 쿠폰 5,000원 * 30명\n------------------------------------------------\n4. 종합 활동 혜택\n활동 종료 후 종합 추첨을 통해 50명 대상 경품 지급\n1) 이동식 TV / 에어랩 / 로봇 청소기 중 택1(50만원 상당) * 2명\n2) 갤럭시 워치(30만원 상당) * 1명\n3) 네이버 페이 포인트 10만원 * 4명\n4) 편의점 쿠폰 2만원 * 15명\n5) 음료 쿠폰 1만원 * 20명\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶10월~12월)2026년 전국 휴게소 만족도 조사 참여자 모집/ 만 20세 이상 ~ 만 69세 이하 휴게소 이용(예정) 국민\n하늘\n26.10.08.\n댓글\n0\n게시글 내 이미지 갯수\n2+\n▶10/23~27 ]은행 어플 AI 서비스 관련 좌담회 / 남녀\n하늘\n26.10.08.\n댓글\n0\n▶10월12일~16일]혈당측정기 1:1 앱테스트 / 50~65세 남녀, 혈당관리자\n하늘\n26.10.08.\n댓글\n0\n▶10/20~21)화장품 설문조사[만30-49세 여성 대학(원)생, 직장인, 프리랜서, 파트타이머]\n하늘\n26.10.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
