      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 10/23~27) 중학생이하 유자녀 아버님) 은행 어플 AI 서비스 관련 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.08. 14:35\n조회 27\n구독\n고유링크) 10/23~27) 중학생이하 유자녀 부모님) 은행 어플 AI 서비스 관련 좌담회\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n참여조건\n조사 내용 : 은행 어플 관련 AI 시나리오에 대한 본인의 의견을 공유하는 오프라인 좌담회 (본인 상황과 AI서비스에 대한 의견을 적극적으로 잘 표현하는 분들 신청 부탁드립니다.)\n공통 조건 : 국내 주요 은행의 모바일 뱅킹 앱을 사용하며, AI 서비스를 사용하고 AI 이해도가 높은자?\n1G : 중학생 이하 자녀가 있고, 자녀에게 모바일 뱅킹으로 용돈을 지급하는 등 자녀 명의 금융 상품을 관리하고 관심이 많은 유자녀 부모\n2G : 만 65~75세 이하로 지원금 수령, 주거비, 공과금 등 일상 금융 업무를 본인이 직접 처리하는 시니어\n3G : 주거래 계좌로 근로소득과 생활비를 직접 관리하며, 금융 상품 (예적금, 투자상품) 및 자산 관리 관심이 많은 직장인\n4G : 주거래 계좌로 사업소득과 생활비를 직접 관리하며, 금융 상품 (예적금, 투자상품) 및 자산 관리 관심이 많은 소상공인 개인사업자\n5G : 자산 관리에 관심이 많으며 부업, 알바, 용돈 등 정기적인 근로 및 투자 소득이 있는 대학(원)생 (남학생의 경우 전역자 우대)\n※ 신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-10-23 ~ 2026-10-27일 중 하루/ 시간은 추후 안내드립니다\n소요시간 150분\n사례비 70,000원\n조사방법 2시간 30분 좌담회\n안내사항 은행 어플 관련 AI 시나리오에 대한 본인의 의견을 나타내는 좌담회입니다. 본인 상황과 AI 서비스에 대한 의견을 적극적으로 잘 표현하는 분들의 많은 신청 부탁드립니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/804?refuser=23341&intro=2\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크)10/23~27)만65~75세 이하로 지원금 수령,주거비,공과금 등 일상 금융 업무를 본인이 직접 처리하는 여성 어르신)은행 어플 AI 서비스 관련 좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n고유링크) 10/23~27) 중학생이하 유자녀 아버님) 은행 어플 AI 서비스 관련 좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n고유링크) 10/23~27) 중학생이하 유자녀 어머니) 은행 어플 AI 서비스 관련 좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n10/20~21)만22세~만29세 여성)건강을 위해 운동을 하고 기록하시는 분(2시간30분 대면좌담회)(10만원)\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
