      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n고유링크) 90분 10만원) 20세 이상 여성) 출산육아 지원정책에 대한 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.08. 16:45\n조회 103\n구독\n고유링크) 90분 10만원) 20세 이상 여성) 출산육아 지원정책에 대한 좌담회\n신청하신분은 재신청 안하셔도 됩니다\n국책연구기관 주관으로, 리서치기관 에스티아이 에서는 출산육아지원정책에 대한 좌담회를 진행합니다.\n출산 전후 경제활동 등에서 겪으신 변화와 필요한 지원 등에 대해 이야기 나누는 자리입니다.\n아래 조건에 해당하시는 분들의 많은 지원을 부탁드립니다.\n일정,장소: 확정시 안내드립니다\n사례비 : 1시간 반 소요, 10만원\n<참가조건>\n마지막 자녀 출산일이 조사일 기준 2년 이내이신 여성분\n마지막 자녀 출산 전에 일을 하고 계셨던 분 (직장인, 자영업, 프리랜서, 특수형태근로 등 무관)\n마지막 자녀 출산 후 육아휴직을 사용하지 않으신 분 (육아휴직이 있는 직장에서 사용 안한 분, 육아휴직이 없는 직업에 종사하시는 분 모두 무관)\n출산 전후로 직업 또는 경제활동에 변화가 있으셨던 분 우대\n<참가신청>\n아래 고유링크로 사전 설문에 응답해 주세요.\n: https://ko.research.net/r/LBZCGTK\n**참가자 선정을 위해 약간의 증빙자료등을 요청드릴 수 있습니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/19(월) 만 25~44세 미혼여성) 식품관련 조사\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n고유링크) 90분 10만원) 20세 이상 여성) 출산육아 지원정책에 대한 좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n2그룹.기존회원 (MG새마을금고 회원이나 예적금 경험 없는 분)만 모집합니다(1,3,4그룹 마감합니다)\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n2그룹.기존회원 (MG새마을금고 회원이나 예적금 경험 없는 분)만 모집합니다(1,3,4그룹 마감합니다)\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
