      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n10/19~22) 카페 점주(아동 친화업소) zoom 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.08. 18:10\n조회 29\n구독\n10/19~22) 카페 점주(아동 친화업소) zoom 좌담회\n신청하신분은 재신청 안하셔도 됩니다 ~\n전국에 계신 카페 점주님들을 대상으로 아동친화업소 관련 좌담회를 진행합니다.\n전국 광역시/중소도시/읍면지역 모두 골고루 진행하며 지방이나 시외곽에 계시는 점주님들도 모두 참여 가능한 좌담회입니다.\n현재 카페 점주님들이 모집이 잘 되지 않아 재차 메일 드립니다.\n● 좌담회 일정 : 10/19(월) ~ 10/22(목) 사이\n*신청자분들의 선호시간에 따라 시간은 바뀔 수 있습니다.\n● 대상 및 조건 :\n1) 현재 카페를 직접 운영하시는 자영업자 분.\n- 프랜차이즈는 가맹점 점주님만 참여 가능하며 키즈카페 점주님은 제외입니다.\n2) PC나 태블릿으로 zoom 참여가 가능하신 분.\n● 좌담회 방법 : 100% zoom 좌담회\n● 좌담회 시간 : 최대 2시간\n● 사례비 : 15만원 (세금 제외 실수령액 136,800원)\n- 계좌이체로 지급되면 좌담회 종료 후 10/27(화)에 일괄 지급됩니다.\n● 회신내용 : 이름 / 연락처 / 성별 / 나이 / 업종 / 상호명 / 영업장위치(시군구까지) / 좌담회 참여 선호일 및 날짜\n예) 홍길동 / 010-0000-0000 / 여 / 40 / 카페 / 케이스탯 / 서울시 서초구 / 3시~5시 사이면 아무떄나 가능\nhttps://forms.gle/JkKoGaF4AtwiRP1N8\n10/19~22) 전국 자영업자(아동친화업소 ) 관련 줌 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/15(목)10대 남녀 (중고등학생) 캔디 맛테스트+미니좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n10/19~22) 카페 점주(아동 친화업소) zoom 좌담회\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n10/19(월) 만35~54세 기혼여성) 식품관련 조사\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n10/19(월) 만 25~44세 미혼여성) 식품관련 조사\n좌담회알바좌담회카페\n26.10.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
